ALTER TABLE "medication_courses" ADD CONSTRAINT "medication_courses_dates_valid" CHECK ("medication_courses"."end_date" IS NULL OR "medication_courses"."end_date" >= "medication_courses"."start_date" OR ("medication_courses"."status" = 'replaced' AND "medication_courses"."end_date" = "medication_courses"."start_date" - 1));